class Solution {
public:
    vector<int> findNumOfValidWords(vector<string>& words, vector<string>& puzzles) {
        unordered_map<int, int> word_counts;
        for (const string& w : words) {
            int mask = 0;
            for (char c : w) mask |= (1 << (c - 'a'));
            if (__builtin_popcount(mask) <= 7) {
                word_counts[mask]++;
            }
        }

        vector<int> res;
        res.reserve(puzzles.size());
        for (const string& p : puzzles) {
            int first_bit = 1 << (p[0] - 'a');
            int rest_mask = 0;
            for (int i = 1; i < 7; ++i) rest_mask |= (1 << (p[i] - 'a'));

            int total = word_counts[first_bit];
            int submask = rest_mask;
            while (submask > 0) {
                if (word_counts.count(submask | first_bit)) {
                    total += word_counts[submask | first_bit];
                }
                submask = (submask - 1) & rest_mask;
            }
            res.push_back(total);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> findNumOfValidWords(String[] words, String[] puzzles) {
        Map<Integer, Integer> wordCounts = new HashMap<>();
        for (String w : words) {
            int mask = 0;
            for (char c : w.toCharArray()) mask |= (1 << (c - 'a'));
            if (Integer.bitCount(mask) <= 7) {
                wordCounts.put(mask, wordCounts.getOrDefault(mask, 0) + 1);
            }
        }

        List<Integer> res = new ArrayList<>(puzzles.length);
        for (String p : puzzles) {
            int firstBit = 1 << (p.charAt(0) - 'a');
            int restMask = 0;
            for (int i = 1; i < 7; i++) restMask |= (1 << (p.charAt(i) - 'a'));

            int total = wordCounts.getOrDefault(firstBit, 0);
            int submask = restMask;
            while (submask > 0) {
                total += wordCounts.getOrDefault(submask | firstBit, 0);
                submask = (submask - 1) & restMask;
            }
            res.add(total);
        }
        return res;
    }
}

var findNumOfValidWords = function(words, puzzles) {
    const wordCounts = new Map();
    const countBits = (n) => {
        let cnt = 0;
        while (n > 0) { cnt += n & 1; n >>= 1; }
        return cnt;
    };

    for (const w of words) {
        let mask = 0;
        for (const c of w) mask |= (1 << (c.charCodeAt(0) - 97));
        if (countBits(mask) <= 7) {
            wordCounts.set(mask, (wordCounts.get(mask) || 0) + 1);
        }
    }

    return puzzles.map(p => {
        const firstBit = 1 << (p.charCodeAt(0) - 97);
        let restMask = 0;
        for (let i = 1; i < 7; i++) restMask |= (1 << (p.charCodeAt(i) - 97));

        let total = wordCounts.get(firstBit) || 0;
        let submask = restMask;
        while (submask > 0) {
            total += wordCounts.get(submask | firstBit) || 0;
            submask = (submask - 1) & restMask;
        }
        return total;
    });
};
